"""R6: 你所生成的任何一个代码文件，其开头处都需另起一行进行清晰的注释声明：“AI-Assisted: Initial draft generated by Claude Code;
reviewed and modified by author.” (a code file's top has, on a line of its own, a comment with that sentence).
Regex validator on the file's first lines: one of lines 1 to 3 is a comment with the sentence, and is not the
encoding line of R5.   R6_ai_note.py FILE ..."""
import re
import sys

sys.path.insert(0, "/opt/enforce")
from common import COMMENT_STARTS, cli, comment_form             # noqa: E402

SENTENCE = "AI-Assisted: Initial draft generated by Claude Code; reviewed and modified by author."
NOTE = re.compile(re.escape(SENTENCE))
TOP = 3


def problems(text: str, where: str) -> list[str]:
    for line in text.split("\n")[:TOP]:
        s = line.strip()
        if NOTE.search(s) and s.startswith(COMMENT_STARTS) and "-*- coding" not in s:
            return []
    line = (comment_form(where) or "# {}").format(SENTENCE)
    return [f"R6 {where}: no comment line with the AI-Assisted sentence at the top; add it on its own line right "
            f"after the encoding line (line 2), here: {line}"]


if __name__ == "__main__":
    cli(problems)
